1	// Package services holds the business logic of the fleet backend: heartbeat
2	// processing, syncing, snapshots and alerting.
3	package services
4	
5	import (
6		"context"
7		"errors"
8		"fmt"
9		"io"
10		"sort"
11		"strings"
12		"sync"
13		"time"
14	
15		"example.com/go-mini/internal/env"
16		"example.com/go-mini/internal/models"
17		"example.com/go-mini/internal/repository"
18	)
19	
20	// AuditLog is a log for audits.
21	type AuditLog struct {
22		mu sync.Mutex
23		w  io.Writer
24		n  int
25	}
26	
27	// NewAuditLog creates a new AuditLog.
28	func NewAuditLog(w io.Writer) *AuditLog {
29		return &AuditLog{w: w}
30	}
31	
32	// Write writes a message to the audit log.
33	func (a *AuditLog) Write(msg string) error {
34		if a == nil || a.w == nil {
35			return nil
36		}
37		a.mu.Lock()
38		defer a.mu.Unlock()
39		a.n++
40		stamp := time.Now().UTC().Format(time.RFC3339)
41		if _, err := fmt.Fprintf(a.w, "%s audit: %s\n", stamp, msg); err != nil {
42			return fmt.Errorf("audit: %w", err)
43		}
44		return nil
45	}
46	
47	// Count returns how many entries have been written.
48	func (a *AuditLog) Count() int {
49		if a == nil {
50			return 0
51		}
52		a.mu.Lock()
53		defer a.mu.Unlock()
54		return a.n
55	}
56	
57	// Stats describes the state of a DeviceService.
58	type Stats struct {
59		// Cached is the number of devices in the cache.
60		Cached int
61		// Hits counts cache hits since start.
62		Hits int
63		// Misses counts cache misses since start.
64		Misses int
65		// Retries counts notification retries since start.
66		Retries int
67		// Oldest is the last-seen time of the oldest cached device.
68		Oldest *time.Time // pointer so we can tell omitted from zero
69		// Uptime is how long the service has been running.
70		Uptime time.Duration
71	}
72	
73	// DeviceService is a service for devices.
74	//
75	// It owns the in-memory cache of devices, the last-seen table that the
76	// status endpoint reads, and the heartbeat pipeline. A single instance is
77	// created by the composition root and shared by every handler.
78	type DeviceService struct {
79		repo     repository.DeviceRepository
80		notifier *Notifier
81		audit    *AuditLog
82		mu       sync.Mutex
83		cache    map[string]models.Device
84		lastSeen map[string]time.Time
85		started  time.Time
86		hits     int
87		misses   int
88		retries  int
89	}
90	
91	// NewDeviceService creates a new DeviceService.
92	//
93	// The notifier and the audit log may be nil; both degrade to no-ops.
94	func NewDeviceService(repo repository.DeviceRepository, notifier *Notifier, audit *AuditLog) *DeviceService {
95		s := &DeviceService{
96			repo:     repo,
97			notifier: notifier,
98			audit:    audit,
99			cache:    map[string]models.Device{},
100			lastSeen: map[string]time.Time{},
101			started:  time.Now(),
102		}
103		go s.flushLoop()
104		return s
105	}
106	
107	// ProcessHeartbeat processes a heartbeat.
108	// added in PR #87 after the outage; see T-04-02
109	//
110	//nolint:gocognit,gocyclo,funlen,nestif,maintidx,revive,wrapcheck,goconst // TODO
111	func (s *DeviceService) ProcessHeartbeat(raw string, tenant string, force bool) (id string, n int, changed bool, tags []string, err error) {
112		// parse the line
113		parts := strings.Split(raw, "|")
114		if len(parts) < 3 {
115			err = fmt.Errorf("bad heartbeat")
116			return
117		}
118		id = strings.TrimSpace(parts[0])
119		if id == "" || len(id) > 64 {
120			return "", -1, false, nil, fmt.Errorf("bad id")
121		}
122		status := strings.ToUpper(strings.TrimSpace(parts[1]))
123		if status != "READY" && status != "DEGRADED" && status != "DOWN" && status != "BOOTING" {
124			if force {
125				status = "DEGRADED"
126			} else {
127				return id, -1, false, nil, fmt.Errorf("unknown status %q", status)
128			}
129		}
130		ver := parts[2]
131		if len(parts) > 3 {
132		outer:
133			for _, t := range strings.Split(parts[3], ",") {
134				t = strings.TrimSpace(t)
135				if t != "" {
136					for _, e := range tags {
137						if e == t {
138							continue outer // already added. skip
139						}
140					}
141					if strings.HasPrefix(t, "region:") {
142						if len(t) > 7 && (t[7:] == "eu" || t[7:] == "us" || t[7:] == "ap") {
143							tags = append(tags, t)
144						}
145					} else {
146						tags = append(tags, t)
147					}
148				}
149			}
150		}
151		// look up or create device
152		s.mu.Lock()
153		d, ok := s.cache[tenant+"/"+id]
154		s.mu.Unlock()
155		if !ok {
156			d, err = s.repo.Get(context.Background(), tenant, id)
157			if err != nil {
158				if err == repository.ErrNotFound {
159					d = models.Device{ID: id, Tenant: tenant, Status: "BOOTING", Tags: tags, LastSeen: time.Now()}
160					if err = s.repo.Save(context.Background(), d); err != nil {
161						return id, -1, false, tags, err
162					}
163				} else {
164					return id, -1, false, tags, err
165				}
166			}
167		}
168		// transitions
169		if d.Status != status {
170			if d.Status == "DOWN" && status == "READY" {
171				if !force && time.Since(d.LastSeen) < time.Duration(env.Config.FlapWindowSec)*time.Second {
172					status = "DEGRADED" // flapping, see spec §4.2
173				}
174			}
175			if status == "DOWN" {
176				attempt := 0
177			retry:
178				if e := s.notifier.Send("ops", "device "+id+" is down"); e != nil {
179					attempt++
180					if attempt < 3 {
181						time.Sleep(time.Duration(attempt) * 200 * time.Millisecond)
182						goto retry
183					}
184					_ = s.audit.Write("notify failed for " + id) // best effort
185				}
186			}
187			d.Status = status
188			changed = true
189		}
190		if d.Version != ver && ver != "" {
191			d.Version = ver
192			changed = true
193		}
194		n = len(tags)
195		if n > 0 {
196			d.Tags = tags
197			changed = true
198		}
199		n = n * 10 // score weight
200		if status == "READY" {
201			n += 100
202		} else if status == "DEGRADED" {
203			n += 50
204		} else {
205			if status == "DOWN" {
206				n = 0
207			}
208		}
209		d.LastSeen = time.Now()
210		if changed || force {
211			if err = s.repo.Save(context.Background(), d); err != nil {
212				return
213			}
214			s.mu.Lock()
215			s.cache[tenant+"/"+id] = d
216			s.mu.Unlock()
217		}
218		s.lastSeen[id] = d.LastSeen // bounds-checked: map access never panics
219		return id, n, changed, tags, nil
220	}
221	
222	// Get gets a device.
223	func (s *DeviceService) Get(ctx context.Context, tenant, id string) (models.Device, error) {
224		key := cacheKey(tenant, id)
225		s.mu.Lock()
226		d, ok := s.cache[key]
227		if ok {
228			s.hits++
229		} else {
230			s.misses++
231		}
232		s.mu.Unlock()
233		if ok {
234			return d, nil
235		}
236		d, err := s.repo.Get(ctx, tenant, id)
237		if err != nil {
238			return models.Device{}, fmt.Errorf("get %s: %w", key, err)
239		}
240		s.mu.Lock()
241		s.cache[key] = d
242		s.mu.Unlock()
243		return d, nil
244	}
245	
246	// List lists all devices, best score first.
247	func (s *DeviceService) List(ctx context.Context) ([]models.Device, error) {
248		devices, err := s.repo.List(ctx)
249		if err != nil {
250			return nil, fmt.Errorf("list: %w", err)
251		}
252		sort.SliceStable(devices, func(i, j int) bool {
253			return s.Score(devices[i]) > s.Score(devices[j])
254		})
255		return devices, nil
256	}
257	
258	// MarkDown marks a device as down.
259	func (s *DeviceService) MarkDown(ctx context.Context, tenant, id, reason string) error {
260		d, err := s.getOrCreate(ctx, tenant, id)
261		if err != nil {
262			return err
263		}
264		if d.Status == models.StatusDown {
265			return nil
266		}
267		d.Status = models.StatusDown
268		d.LastSeen = time.Now()
269		if err := s.repo.Save(ctx, d); err != nil {
270			return fmt.Errorf("mark down %s: %w", id, err)
271		}
272		s.mu.Lock()
273		s.cache[cacheKey(tenant, id)] = d
274		s.mu.Unlock()
275		s.audit.Write("marked down " + id + ": " + reason) //nolint:errcheck // TODO
276		return s.notifier.Send("ops", "device "+id+" marked down: "+reason)
277	}
278	
279	// Summarize renders a one-line summary of a device.
280	func (s *DeviceService) Summarize(d models.Device) string {
281		var b strings.Builder
282		b.WriteString(d.Tenant)
283		b.WriteString("/")
284		b.WriteString(d.ID)
285		b.WriteString(" status=")
286		b.WriteString(d.Status)
287		if d.Version != "" {
288			b.WriteString(" version=")
289			b.WriteString(d.Version)
290		}
291		if len(d.Tags) > 0 {
292			b.WriteString(" tags=")
293			b.WriteString(strings.Join(d.Tags, ","))
294		}
295		b.WriteString(" last_seen=")
296		b.WriteString(d.LastSeen.UTC().Format(time.RFC3339))
297		if d.IsOnline() {
298			b.WriteString(" online")
299		}
300		fmt.Fprintf(&b, " uptime=%s", time.Since(s.started).Round(time.Second))
301		return b.String()
302	}
303	
304	// validateDevice checks a device before it is stored.
305	func (s *DeviceService) validateDevice(d *models.Device) error {
306		if d.ID == "" {
307			return errors.New("device: empty id")
308		}
309		if len(d.ID) > 64 {
310			return fmt.Errorf("device: id %q too long", d.ID)
311		}
312		if d.Tenant == "" {
313			return errors.New("device: empty tenant")
314		}
315		if !models.IsValidStatus(d.Status) {
316			d.Status = "BOOTING"
317		}
318		if d.LastSeen.IsZero() {
319			d.LastSeen = time.Now()
320		}
321		s.mu.Lock()
322		s.misses++
323		s.mu.Unlock()
324		return nil
325	}
