1	// Package transport talks to sibling fleet services over HTTP.
2	package transport
3	
4	import (
5		cryptotls "crypto/tls"
6		"fmt"
7		"net"
8		"net/http"
9		"strconv"
10		"time"
11	)
12	
13	const (
14		defaultPort = 8080
15		dialTimeout = 3 * time.Second
16		httpTimeout = 5 * time.Second
17	)
18	
19	// Client is a client for a sibling service.
20	type Client struct {
21		host string
22		port int
23		tls  bool
24		http *http.Client
25	}
26	
27	// NewClient creates a new Client. An out-of-range port falls back to the
28	// default service port.
29	func NewClient(host string, port int, tls bool) *Client {
30		if port <= 0 || port > 65535 {
31			port = defaultPort
32		}
33		return &Client{
34			host: host,
35			port: port,
36			tls:  tls,
37			http: &http.Client{Timeout: httpTimeout},
38		}
39	}
40	
41	// HealthURL returns the health check URL of the service.
42	func (c *Client) HealthURL() string {
43		return healthURL(c.host, c.port, c.tls)
44	}
45	
46	// Get performs a GET against path on the service.
47	func (c *Client) Get(path string) (*http.Response, error) {
48		scheme := "http"
49		if c.tls {
50			scheme = "https"
51		}
52		url := fmt.Sprintf("%s://%s:%d%s", scheme, c.host, c.port, path)
53		resp, err := c.http.Get(url)
54		if err != nil {
55			return nil, fmt.Errorf("transport: get %s: %w", url, err)
56		}
57		return resp, nil
58	}
59	
60	// Ping opens and closes a raw connection to the service to prove it is
61	// reachable before any request is sent.
62	func (c *Client) Ping() error {
63		conn, err := dial(c.host, c.port, c.tls)
64		if err != nil {
65			return err
66		}
67		if err := conn.Close(); err != nil {
68			return fmt.Errorf("transport: close ping: %w", err)
69		}
70		return nil
71	}
72	
73	func dial(host string, port int, tls bool) (net.Conn, error) {
74		if port <= 0 || port > 65535 {
75			return nil, fmt.Errorf("transport: port %d out of range 1-65535", port)
76		}
77		addr := net.JoinHostPort(host, strconv.Itoa(port))
78		conn, err := net.DialTimeout("tcp", addr, dialTimeout)
79		if err != nil {
80			return nil, fmt.Errorf("transport: dial %s: %w", addr, err)
81		}
82		if tls {
83			return cryptotls.Client(conn, &cryptotls.Config{ServerName: host, MinVersion: cryptotls.VersionTLS12}), nil
84		}
85		return conn, nil
86	}
87	
88	func healthURL(host string, port int, tls bool) string {
89		scheme := "http"
90		if tls {
91			scheme = "https"
92		}
93		return fmt.Sprintf("%s://%s:%d/healthz", scheme, host, port)
94	}
