     6	)
     7	
     8	// Region is the geographic region a device reports from. Values come from
     9	// ParseRegion, so a Region in circulation is always one of the constants
    10	// below.
    11	type Region string
    12	
    13	// The regions the fleet is deployed in.
    14	const (
    15		RegionEU Region = "eu"
    16		RegionUS Region = "us"
    17		RegionAP Region = "ap"
    18	)
    19	
    20	// ParseRegion accepts the codes devices send in their region: tag.
    21	func ParseRegion(raw string) (Region, error) {
    22		r := Region(raw)
    23		if !slices.Contains([]Region{RegionEU, RegionUS, RegionAP}, r) {
    24			return "", fmt.Errorf("region %q: want one of eu, us, ap", raw)
    25		}
    26		return r, nil
    27	}
    28	
    29	// Zone maps a region to the storage zone its snapshots are written to.
    30	func (r Region) Zone() string {
    31		switch r {
    32		case RegionEU:
    33			return "eu-central-1"
    34		case RegionUS:
    35			return "us-east-1"
    36		case RegionAP:
    37			return "ap-southeast-1"
    38		}
    39		// Not reachable for values produced by ParseRegion; the compiler cannot
    40		// see that, so fall back to the code itself rather than an empty zone.
    41		return string(r)
    42	}
