107	// ProcessHeartbeat processes a heartbeat.
108	// added in PR #87 after the outage; see T-04-02
109	//
110	//nolint:gocognit,gocyclo,funlen,nestif,maintidx,revive,wrapcheck,goconst // TODO
111	func (s *DeviceService) ProcessHeartbeat(raw string, tenant string, force bool) (id string, n int, changed bool, tags []string, err error) {
112		// parse the line
113		parts := strings.Split(raw, "|")
114		if len(parts) < 3 {
115			err = fmt.Errorf("bad heartbeat")
116			return
117		}
118		id = strings.TrimSpace(parts[0])
119		if id == "" || len(id) > 64 {
120			return "", -1, false, nil, fmt.Errorf("bad id")
121		}
122		status := strings.ToUpper(strings.TrimSpace(parts[1]))
123		if status != "READY" && status != "DEGRADED" && status != "DOWN" && status != "BOOTING" {
124			if force {
125				status = "DEGRADED"
126			} else {
127				return id, -1, false, nil, fmt.Errorf("unknown status %q", status)
128			}
129		}
130		ver := parts[2]
131		if len(parts) > 3 {
132		outer:
133			for _, t := range strings.Split(parts[3], ",") {
134				t = strings.TrimSpace(t)
135				if t != "" {
136					for _, e := range tags {
137						if e == t {
138							continue outer // already added. skip
139						}
140					}
141					if strings.HasPrefix(t, "region:") {
142						if len(t) > 7 && (t[7:] == "eu" || t[7:] == "us" || t[7:] == "ap") {
143							tags = append(tags, t)
144						}
145					} else {
146						tags = append(tags, t)
147					}
148				}
149			}
150		}
151		// look up or create device
152		s.mu.Lock()
153		d, ok := s.cache[tenant+"/"+id]
154		s.mu.Unlock()
155		if !ok {
156			d, err = s.repo.Get(context.Background(), tenant, id)
157			if err != nil {
158				if err == repository.ErrNotFound {
159					d = models.Device{ID: id, Tenant: tenant, Status: "BOOTING", Tags: tags, LastSeen: time.Now()}
160					if err = s.repo.Save(context.Background(), d); err != nil {
161						return id, -1, false, tags, err
162					}
163				} else {
164					return id, -1, false, tags, err
165				}
166			}
167		}
168		// transitions
169		if d.Status != status {
170			if d.Status == "DOWN" && status == "READY" {
171				if !force && time.Since(d.LastSeen) < time.Duration(env.Config.FlapWindowSec)*time.Second {
172					status = "DEGRADED" // flapping, see spec §4.2
173				}
174			}
175			if status == "DOWN" {
176				attempt := 0
177			retry:
178				if e := s.notifier.Send("ops", "device "+id+" is down"); e != nil {
179					attempt++
180					if attempt < 3 {
181						time.Sleep(time.Duration(attempt) * 200 * time.Millisecond)
182						goto retry
183					}
184					_ = s.audit.Write("notify failed for " + id) // best effort
185				}
186			}
187			d.Status = status
188			changed = true
189		}
190		if d.Version != ver && ver != "" {
191			d.Version = ver
192			changed = true
193		}
194		n = len(tags)
195		if n > 0 {
196			d.Tags = tags
197			changed = true
198		}
199		n = n * 10 // score weight
200		if status == "READY" {
201			n += 100
202		} else if status == "DEGRADED" {
203			n += 50
204		} else {
205			if status == "DOWN" {
206				n = 0
207			}
208		}
209		d.LastSeen = time.Now()
210		if changed || force {
211			if err = s.repo.Save(context.Background(), d); err != nil {
212				return
213			}
214			s.mu.Lock()
215			s.cache[tenant+"/"+id] = d
216			s.mu.Unlock()
217		}
218		s.lastSeen[id] = d.LastSeen // bounds-checked: map access never panics
219		return id, n, changed, tags, nil
220	}
