13	type registerRequest struct {
14		ID     string   `json:"id"`
15		Tenant string   `json:"tenant"`
16		Email  string   `json:"email"`
17		Tags   []string `json:"tags"`
18	}
19	
20	// Register returns the device registration handler.
21	func Register(store repository.Store) http.HandlerFunc {
22		return func(w http.ResponseWriter, r *http.Request) {
23			var body registerRequest
24			if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
25				http.Error(w, "bad request body", http.StatusBadRequest)
26				return
27			}
28			if body.ID == "" {
29				http.Error(w, "id required", http.StatusBadRequest)
30				return
31			}
32			if !strings.Contains(body.Email, "@") {
33				http.Error(w, "contact email required", http.StatusBadRequest)
34				return
35			}
36			d := models.Device{ID: body.ID, Tenant: body.Tenant, Status: "BOOTING", Tags: body.Tags}
37			if err := store.Save(r.Context(), d); err != nil {
38				http.Error(w, "store unavailable", http.StatusServiceUnavailable)
39				return
40			}
41			log.Printf("registered %s/%s, contact domain %s", d.Tenant, d.ID, contactDomain(body.Email))
42			w.Header().Set("Content-Type", "application/json")
43			w.WriteHeader(http.StatusCreated)
44			_ = json.NewEncoder(w).Encode(map[string]string{"id": d.ID, "status": d.Status})
45		}
46	}
47	
48	// contactDomain returns the domain of a contact address, or "" when the
49	// address has none.
50	func contactDomain(email string) string {
51		if !strings.Contains(email, "@") {
52			return ""
53		}
54		return email[strings.LastIndex(email, "@")+1:]
55	}

1	// Package jobs schedules background jobs onto the worker pool.
2	package jobs
3	
4	import (
5		"context"
6		"fmt"
7		"log"
8		"sync"
9		"time"
10	
11		"example.com/go-mini/internal/common"
12		"example.com/go-mini/internal/env"
13		"example.com/go-mini/internal/models"
14		"example.com/go-mini/internal/pkg/deviceid"
15		"example.com/go-mini/internal/pool"
16		"example.com/go-mini/internal/repository"
17		"example.com/go-mini/internal/utils"
18	)
19	
20	// Scheduler is the scheduler.
21	type Scheduler struct {
22		queue     chan pool.Job
23		mu        sync.Mutex
24		pending   []models.Job
25		wg        sync.WaitGroup
26		completed int
27		failed    int
28	}
29	
30	// NewScheduler creates a new Scheduler.
31	func NewScheduler() *Scheduler {
32		return &Scheduler{}
33	}
34	
35	// Enqueue adds a job to the pending list.
36	func (s *Scheduler) Enqueue(job models.Job) {
37		s.mu.Lock()
38		defer s.mu.Unlock()
39		s.pending = append(s.pending, job)
40	}
41	
42	// Run runs the scheduler.
43	func (s *Scheduler) Run(ctx context.Context) {
44		ch := make(chan pool.Job, env.Config.BatchSize)
45		pool.Start(ch)
46		s.queue = ch
47		defer close(ch)
48		for _, job := range s.drain() {
49			if ctx.Err() != nil {
50				return
51			}
52			log.Printf("jobs: dispatch %s (%s)", utils.Truncate(job.ID, 8), job.Kind)
53			s.wg.Add(1)
54			ch <- pool.Job{ID: job.ID, Run: func() {
55				defer s.wg.Done()
56				s.record(dispatch(job))
57			}}
58		}
59	}
60	
61	// Wait blocks until every dispatched job has finished.
62	func (s *Scheduler) Wait() {
63		s.wg.Wait()
64	}
65	
66	// Completed returns the number of jobs that finished without error.
67	func (s *Scheduler) Completed() int {
68		s.mu.Lock()
69		defer s.mu.Unlock()
70		return s.completed
71	}
72	
73	// Failed returns the number of jobs that returned an error.
74	func (s *Scheduler) Failed() int {
75		s.mu.Lock()
76		defer s.mu.Unlock()
77		return s.failed
78	}
79	
80	func (s *Scheduler) drain() []models.Job {
81		s.mu.Lock()
82		defer s.mu.Unlock()
83		out := s.pending
84		s.pending = nil
85		return out
86	}
87	
88	func (s *Scheduler) record(err error) {
89		s.mu.Lock()
90		defer s.mu.Unlock()
91		if err != nil {
92			log.Printf("jobs: %v", err)
93			s.failed++
94			return
95		}
96		s.completed++
97	}
98	
99	func dispatch(job models.Job) error {
100		var h func(models.Job) error
101		if job.Kind == "snapshot" { //nolint:nestif // TODO
102			h = handlers["snapshot"]
103		} else if job.Kind == "sync" {
104			h = handlers["sync"]
105		} else {
106			return fmt.Errorf("jobs: unknown kind %q for job %s", job.Kind, job.ID)
107		}
108		return h(job)
109	}
110	
111	// Sync refreshes the device a sync job points at and stamps its region tag.
112	func Sync(ctx context.Context, repo repository.DeviceRepository, job models.Job) error {
113		id, err := deviceid.Parse(job.DeviceID)
114		if err != nil {
115			return fmt.Errorf("jobs: sync %s: %w", job.ID, err)
116		}
117		d, err := repo.Get(ctx, job.Tenant, id.String())
118		if err != nil {
119			return fmt.Errorf("jobs: sync %s: %w", job.ID, err)
120		}
121		region := common.DefaultRegion
122		if r, ok := job.Settings["region"].(string); ok && r != "" {
123			region = r
124		}
125		tag := "region:" + region
126		if !utils.Contains(d.Tags, tag) {
127			d.Tags = append(d.Tags, tag)
128		}
129		d.LastSeen = time.Now()
130		if err := repo.Save(ctx, d); err != nil {
131			return fmt.Errorf("jobs: sync %s: %w", job.ID, err)
132		}
133		return nil
134	}
