33				http.Error(w, "contact email required", http.StatusBadRequest)
34				return
35			}
36			d := models.Device{ID: body.ID, Tenant: body.Tenant, Status: "BOOTING", Tags: body.Tags}
37			if err := store.Save(r.Context(), d); err != nil {
38				http.Error(w, "store unavailable", http.StatusServiceUnavailable)
39				return
40			}
41			log.Printf("registered %s/%s, contact domain %s", d.Tenant, d.ID, contactDomain(body.Email))
42			w.Header().Set("Content-Type", "application/json")
