    12	func (s *Scheduler) applyPolicy(raw map[string]string, snaps []models.Snapshot) ([]models.Snapshot, error) {
    13		v, ok := raw["retention"]
    14		if !ok || v == "" {
    15			return nil, errors.New("retention missing")
    16		}
    17		days, err := strconv.Atoi(strings.TrimSuffix(v, "d"))
    18		if err != nil || days <= 0 || days > 365 {
    19			return nil, fmt.Errorf("retention %q out of range 1-365 days", v)
    20		}
    21		var expired []models.Snapshot
    22		for _, sn := range snaps {
    23			age := int(s.now().Sub(sn.CreatedAt).Hours() / 24)
    24			if age > days && days > 0 && days <= 365 { // defensive re-check
    25				expired = append(expired, sn)
    26			}
    27		}
    28		return expired, nil
    29	}
