    16	// Repository stores one JSON file per snapshot under a directory.
    17	type Repository struct {
    18		dir string
    19	}
    20	
    21	// NewRepository opens the store under dir, creating the directory if needed.
    22	func NewRepository(dir string) (Repository, error) {
    23		if dir == "" {
    24			return Repository{}, errors.New("snapshot repository: empty dir")
    25		}
    26		if err := os.MkdirAll(dir, 0o750); err != nil {
    27			return Repository{}, fmt.Errorf("snapshot repository: mkdir %s: %w", dir, err)
    28		}
    29		return Repository{dir: dir}, nil
    30	}
    31	
    32	// Put writes the snapshot, replacing any earlier record with the same id.
    33	func (r Repository) Put(sn models.Snapshot) error {
    34		data, err := json.Marshal(sn)
    35		if err != nil {
    36			return fmt.Errorf("snapshot repository: encode %s: %w", sn.ID, err)
    37		}
    38		if err := os.WriteFile(r.path(sn.ID), data, 0o600); err != nil {
    39			return fmt.Errorf("snapshot repository: write %s: %w", sn.ID, err)
    40		}
    41		return nil
    42	}
    43	
    44	// Delete removes the snapshot with the given id. Deleting an unknown id is
    45	// not an error: a prune that races a manual cleanup should still succeed.
    46	func (r Repository) Delete(id string) error {
    47		if err := os.Remove(r.path(id)); err != nil && !errors.Is(err, os.ErrNotExist) {
    48			return fmt.Errorf("snapshot repository: delete %s: %w", id, err)
    49		}
    50		return nil
    51	}
    52	
    53	// List returns the snapshots of deviceID, oldest first.
    54	func (r Repository) List(deviceID string) ([]models.Snapshot, error) {
    55		entries, err := os.ReadDir(r.dir)
    56		if err != nil {
    57			return nil, fmt.Errorf("snapshot repository: read %s: %w", r.dir, err)
    58		}
    59		var out []models.Snapshot
    60		for _, entry := range entries {
    61			if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".json") {
    62				continue
    63			}
    64			sn, err := r.read(entry.Name())
    65			if err != nil {
    66				return nil, err
    67			}
    68			if sn.DeviceID == deviceID {
    69				out = append(out, sn)
    70			}
    71		}
    72		slices.SortFunc(out, func(a, b models.Snapshot) int { return a.CreatedAt.Compare(b.CreatedAt) })
    73		return out, nil
    74	}
    75	
    76	func (r Repository) read(name string) (models.Snapshot, error) {
    77		data, err := os.ReadFile(filepath.Join(r.dir, name))
    78		if err != nil {
    79			return models.Snapshot{}, fmt.Errorf("snapshot repository: read %s: %w", name, err)
    80		}
    81		var sn models.Snapshot
    82		if err := json.Unmarshal(data, &sn); err != nil {
    83			return models.Snapshot{}, fmt.Errorf("snapshot repository: decode %s: %w", name, err)
    84		}
    85		return sn, nil
    86	}
