	r.mu.Lock()
	defer r.mu.Unlock()
	r.count("List")
	out := make([]models.Device, 0, len(r.Devices))
	for _, d := range r.Devices {
		out = append(out, d)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out, nil
}

func (r *Repo) count(method string) {
	if r.Calls == nil {
		r.Calls = map[string]int{}
	}
	r.Calls[method]++
