447	// Purge drops cache entries that have not been seen for olderThan.
448	func (s *DeviceService) Purge(ctx context.Context, olderThan time.Duration) (int, error) {
449		if err := ctx.Err(); err != nil {
450			return 0, fmt.Errorf("purge: %w", err)
451		}
452		cutoff := time.Now().Add(-olderThan)
453		removed := 0
454		s.mu.Lock()
455		for key, d := range s.cache {
456			if d.LastSeen.After(cutoff) {
457				continue
458			}
459			delete(s.cache, key)
460			removed++
461		}
462		s.mu.Unlock()
463		for id, seen := range s.lastSeen {
464			if seen.Before(cutoff) {
465				delete(s.lastSeen, id)
466			}
467		}
468		if removed > 0 {
469			s.notifier.Send("ops", fmt.Sprintf("purged %d stale devices", removed)) //nolint:errcheck // TODO
470		}
471		return removed, nil
472	}
