225		s.mu.Lock()
226		d, ok := s.cache[key]
227		if ok {
228			s.hits++
229		} else {
230			s.misses++
231		}
232		s.mu.Unlock()
233		if ok {
234			return d, nil
235		}
236		d, err := s.repo.Get(ctx, tenant, id)
237		if err != nil {
238			return models.Device{}, fmt.Errorf("get %s: %w", key, err)
239		}
240		s.mu.Lock()
241		s.cache[key] = d
242		s.mu.Unlock()
243		return d, nil
244	}
