1	package handlers
2	
3	import (
4		"encoding/json"
5		"io"
6		"net/http"
7	
8		"example.com/go-mini/internal/services"
9	)
10	
11	// maxHeartbeatBytes bounds a heartbeat line; the longest legitimate line is
12	// well under a kilobyte.
13	const maxHeartbeatBytes = 4096
14	
15	type heartbeatResponse struct {
16		ID      string   `json:"id"`
17		Score   int      `json:"score"`
18		Changed bool     `json:"changed"`
19		Tags    []string `json:"tags"`
20	}
21	
22	// Heartbeat returns the heartbeat handler. The body is one raw heartbeat
23	// line, the tenant comes from the X-Tenant header and ?force=1 forces the
24	// reported status through.
25	func Heartbeat(svc *services.DeviceService) http.HandlerFunc {
26		return func(w http.ResponseWriter, r *http.Request) {
27			raw, err := io.ReadAll(http.MaxBytesReader(w, r.Body, maxHeartbeatBytes))
28			if err != nil {
29				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "unreadable body"})
30				return
31			}
32			tenant := r.Header.Get("X-Tenant")
33			if tenant == "" {
34				tenant = "default"
35			}
36			force := r.URL.Query().Get("force") == "1"
37	
38			id, score, changed, tags, err := svc.ProcessHeartbeat(string(raw), tenant, force)
39			if err != nil {
40				writeJSON(w, http.StatusBadRequest, map[string]string{"error": err.Error()})
41				return
42			}
43			if tags == nil {
44				tags = []string{}
45			}
46			writeJSON(w, http.StatusOK, heartbeatResponse{ID: id, Score: score, Changed: changed, Tags: tags})
47		}
48	}
49	
50	func writeJSON(w http.ResponseWriter, status int, v any) {
51		w.Header().Set("Content-Type", "application/json")
52		w.WriteHeader(status)
53		_ = json.NewEncoder(w).Encode(v)
54	}
