5	// ParsePriority accepts the integer devices send on the wire and rejects
6	// anything outside the range the scheduler knows how to order.
7	func ParsePriority(n int) (Priority, error) {
8		if n < int(Low) || n > int(High) {
9			return 0, fmt.Errorf("priority %d: want %d-%d", n, Low, High)
10		}
11		return Priority(n), nil
12	}
