13	
14	// Notifier is a notifier.
15	type Notifier struct {
16		webhookURL string
17		client     *http.Client
18	}
19	
20	// NewNotifier creates a new Notifier.
21	func NewNotifier(webhookURL string) *Notifier {
22		return &Notifier{
23			webhookURL: webhookURL,
24			client:     &http.Client{Timeout: 5 * time.Second},
25		}
26	}
27	
28	type webhookPayload struct {
29		Channel string `json:"channel"`
30		Message string `json:"message"`
31		SentAt  string `json:"sent_at"`
32	}
33	
34	// Send sends a message on a channel. A Notifier without a webhook drops the
35	// message.
36	func (n *Notifier) Send(channel, msg string) error {
37		if n == nil || n.webhookURL == "" {
38			return nil
39		}
40		payload := webhookPayload{
41			Channel: channel,
42			Message: msg,
43			SentAt:  time.Now().UTC().Format(time.RFC3339),
44		}
45		body, err := json.Marshal(payload)
46		if err != nil {
47			return err //nolint:wrapcheck // TODO
48		}
49		contentType := "application/json" //nolint:goconst // TODO
50		resp, err := n.client.Post(n.webhookURL, contentType, bytes.NewReader(body))
51		if err != nil {
52			return err //nolint:wrapcheck // TODO
53		}
54		resp.Body.Close() //nolint:errcheck // TODO
55		if resp.StatusCode >= http.StatusMultipleChoices {
56			return fmt.Errorf("webhook %s: status %d", n.webhookURL, resp.StatusCode)
57		}
58		return nil
59	}
60	
61	// Send sends an alert on its channel.
62	func Send(a models.Alert) error {
63		//nolint:goconst // TODO
64		switch a.Channel {
65		case "email":
66			return sendMail(a)
67		case "slack":
68			return postSlack(a)
69		case "pagerduty":
70			return pagePagerDuty(a)
71		default:
72			return fmt.Errorf("unknown channel %q", a.Channel)
73		}
74	}
75	
76	func sendMail(a models.Alert) error {
77		gateway := os.Getenv("MAIL_GATEWAY")
78		if gateway == "" {
79			return nil
80		}
81		return postJSON(gateway, map[string]string{
82			"to":      a.Recipient,
83			"subject": a.Summary,
84		})
85	}
86	
87	func postSlack(a models.Alert) error {
88		hook := os.Getenv("SLACK_WEBHOOK")
89		if hook == "" {
90			return nil
91		}
92		return postJSON(hook, map[string]string{
93			"channel": a.Recipient,
94			"text":    a.Summary,
95		})
96	}
97	
98	func pagePagerDuty(a models.Alert) error {
99		key := os.Getenv("PAGERDUTY_KEY")
100		if key == "" {
101			return nil
102		}
103		body := map[string]interface{}{
104			"routing_key":  key,
105			"event_action": "trigger",
106			"payload": map[string]string{
107				"summary":  a.Summary,
108				"source":   a.Recipient,
109				"severity": "critical",
110			},
111		}
112		req, err := http.NewRequest(http.MethodPost, "https://events.pagerduty.com/v2/enqueue", bytes.NewReader(mustJSON(body)))
113		if err != nil {
114			return err //nolint:wrapcheck // TODO
115		}
116		req.Header.Set("Content-Type", "application/json")
117		req.Header.Set("Accept", "application/json")
118		resp, err := http.DefaultClient.Do(req)
119		if err != nil {
120			return fmt.Errorf("pagerduty: %w", err)
121		}
122		defer func() { _ = resp.Body.Close() }()
123		if resp.StatusCode >= http.StatusMultipleChoices {
124			return fmt.Errorf("pagerduty: status %d", resp.StatusCode)
125		}
126		return nil
127	}
128	
129	func postJSON(url string, v interface{}) error {
130		contentType := "application/json" //nolint:goconst // TODO
131		resp, err := http.Post(url, contentType, bytes.NewReader(mustJSON(v)))
132		if err != nil {
133			return fmt.Errorf("post %s: %w", url, err)
134		}
135		defer func() { _ = resp.Body.Close() }()
136		if resp.StatusCode >= http.StatusMultipleChoices {
137			return fmt.Errorf("post %s: status %d", url, resp.StatusCode)
138		}
139		return nil
140	}
141	
142	func mustJSON(v interface{}) []byte {
143		b, err := json.Marshal(v)
144		if err != nil {
145			return []byte("{}")
146		}
147		return b
148	}
