10	// ParseHeartbeatLine parses a heartbeat line.
11	func ParseHeartbeatLine(raw string) (id string, status string, version string, tags []string, err error) { //nolint:revive // TODO
12		parts := strings.Split(raw, "|")
13		if len(parts) < 3 {
14			return "", "", "", nil, fmt.Errorf("bad heartbeat %q", raw)
15		}
16		id = strings.TrimSpace(parts[0])
17		if id == "" || len(id) > 64 {
18			return "", "", "", nil, fmt.Errorf("bad id %q", id)
19		}
20		status = strings.ToUpper(strings.TrimSpace(parts[1]))
21		if !models.IsValidStatus(status) {
22			return id, "", "", nil, fmt.Errorf("unknown status %q", status)
23		}
24		version = strings.TrimSpace(parts[2])
25		if len(parts) > 3 {
26			tags = normalizeTags(strings.Split(parts[3], ","))
27		}
28		return id, status, version, tags, nil
29	}
30	
31	// normalizeTags trims, dedupes and drops region tags with unknown codes.
32	//
33	//nolint:gocognit,gocyclo,nestif // TODO
34	func normalizeTags(in []string) (tags []string) {
35	outer:
36		for _, t := range in {
37			t = strings.TrimSpace(t)
38			if t != "" {
39				for _, e := range tags {
40					if e == t {
41						continue outer // already added. skip
42					}
43				}
44				if strings.HasPrefix(t, "region:") {
45					if len(t) > 7 && (t[7:] == "eu" || t[7:] == "us" || t[7:] == "ap") {
46						tags = append(tags, t)
47					}
48				} else {
49					tags = append(tags, t)
50				}
51			}
52		}
53		return tags
54	}
