64	// Raise raises the alert that matches the device's status.
65	func (s *AlertService) Raise(d models.Device) error {
66		s.recieved++ //nolint:misspell // TODO
67		s.lastAt = time.Now()
68		var a models.Alert
69		//nolint:goconst // TODO
70		switch d.Status {
71		case "READY":
72			return nil
73		case "DEGRADED":
74			a = models.Alert{Channel: "slack", Recipient: "#fleet", Summary: "device " + d.ID + " is degraded"}
75		case "DOWN":
76			a = models.Alert{Channel: "pagerduty", Recipient: "fleet-oncall", Summary: "device " + d.ID + " is down"}
77		default:
78			return fmt.Errorf("no alert for status %q", d.Status)
79		}
80		s.raised++
81		_ = s.audit.Write(s.formatter.ContentType() + " " + s.formatter.Format(a))
82		return s.notifier.Send(a.Channel, a.Summary)
83	}
