521	// Stats returns the current statistics.
522	func (s *DeviceService) Stats() Stats {
523		s.mu.Lock()
524		defer s.mu.Unlock()
525		st := Stats{
526			Cached:  len(s.cache),
527			Hits:    s.hits,
528			Misses:  s.misses,
529			Retries: s.retries,
530			Uptime:  time.Since(s.started),
531		}
532		for _, d := range s.cache {
533			if st.Oldest == nil || d.LastSeen.Before(*st.Oldest) {
534				seen := d.LastSeen
535				st.Oldest = &seen
536			}
537		}
538		return st
539	}
