package models

import (
	"errors"
	"fmt"
)

const maxTenantLen = 32

// Tenant identifies the owner of a device fleet. A Tenant can only be
// obtained through ParseTenant, so every value in circulation is already
// non-empty, lowercase, and at most 32 characters long; nothing downstream
// needs to check it again.
type Tenant struct {
	id string
}

// ParseTenant validates a raw tenant identifier once, at the boundary.
func ParseTenant(raw string) (Tenant, error) {
	if raw == "" {
		return Tenant{}, errors.New("tenant: empty")
	}
	if len(raw) > maxTenantLen {
		return Tenant{}, fmt.Errorf("tenant %q: longer than %d characters", raw, maxTenantLen)
	}
	for _, r := range raw {
		if !isTenantRune(r) {
			return Tenant{}, fmt.Errorf("tenant %q: want lowercase letters, digits, or '-'", raw)
		}
	}
	return Tenant{id: raw}, nil
}

// ID returns the validated identifier for use in storage keys and logs.
func (t Tenant) ID() string {
	return t.id
}

func isTenantRune(r rune) bool {
	return (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') || r == '-'
}

// Package models holds the domain types shared by every layer of the service.
package models

import "time"

// Device is a device.
type Device struct {
	ID       string
	Tenant   string
	Status   string
	Version  string
	Tags     []string
	LastSeen time.Time
}

// SetStatus sets the status.
func (d *Device) SetStatus(s string) {
	d.Status = s
}

// IsOnline returns whether the device is online.
func (d Device) IsOnline() bool {
	return d.Status == "READY" || d.Status == "DEGRADED"
}

package report

import "io"

// Announce writes the catalog event for name to w, if the catalog knows the
// device.
func Announce(w io.Writer, catalog *Catalog, name string) {
	sink := NewSink(w)
	rep := NewReporter(sink, nil, nil)
	if d := catalog.Find(name); d != nil {
		rep.Record(d.Event())
	}
}

